sys_ui_action.script:
//gs.eventQueue('x_hccc_csoir.notify.supervisor', current);
//gs.addInfoMessage("Supervisor notified");
current.update();
if (current.covered_by_collective_agreement == "") {
	//gs.addErrorMessage("Please fill-out the field 'Investigation details' before marking the investigation as completed");
	gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.covered_by_collective_agreement"));
}
if (current.union == "") {
	//gs.addErrorMessage("Please fill-out the field 'Decision' before marking the investigation as completed");
	gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.union"));
}
if(current.union != "Unrepresented"){
	if (current.rep_name == "") {
		gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.rep_name"));
	}
}

if (current.employer_s_response_to_the_joint_investigators_report == "") {
	gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.employer_s_response_to_the_joint_investigators_report"));
}

if (current.sc_action_plan == "") {
	gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.sc_action_plan"));
}
action.setRedirectURL(current);
if (current.covered_by_collective_agreement != "" && current.union != "" && current.employer_s_response_to_the_joint_investigators_report != "" && current.sc_action_plan != "") {
	if(current.union != "Unrepresented"){
		if (current.rep_name != "") {
			current.state = 108;
			current.update();
			action.setRedirectURL(current);
		}
	}
	else{
		current.state = 108;
		current.update();
		action.setRedirectURL(current);
	}
}

// || (current.state == 102 && current.hr_service.value=="refusal_to_work" )
